#!/usr/bin/env python3
"""Hermes conflict resolution core — stdlib only, no git side effects.

For every conflicted path we ask two questions:

  1. what kind of file is it?  -> binary / derived / source  (`classify_conflict`)
  2. how do we resolve it?     -> regenerate, deterministic merge, LLM, or escalate

Design rules, in order of authority:

* A derived file is NEVER sent to the LLM. A model rewriting a generated file
  produces something that looks plausible and is wrong (duello paid for it: a
  truncated generated file broke the typecheck on a dozen PRs). It is
  regenerated with the repository's own toolchain instead.
* The LLM leg only ever returns a *candidate*. `accept_llm_output` throws away
  anything that still carries conflict markers, is empty, or is absurdly sized.
* When no leg can prove a result, the file stays unresolved and the caller
  escalates to a human. Nothing is ever guessed, nothing fails silently.

`--selftest` replays in-memory cases (derived, JSON merge, LLM leg injected,
insoluble) and checks the wiring of the direct leg (Fireworks endpoint + model,
key present => available) with no secret and no network.
"""
from __future__ import annotations

import json
import os
import sys

FIREWORKS_URL = "https://api.fireworks.ai/inference/v1/chat/completions"
FIREWORKS_DEFAULT_MODEL = "accounts/fireworks/models/deepseek-v4p1-flash-1017"
KEY_ENV = "FIREWORKS_API_KEY"
MODEL_ENV = "HERMES_LLM_MODEL"
LLM_TIMEOUT = 90
# A side bigger than this cannot be sent without truncation, and a truncated
# input yields a broken output: above the limit the LLM leg declines.
MAX_LLM_SIDE = 120_000
# A merged file larger than this multiple of the biggest input is not a merge.
MAX_GROWTH = 4
MARKERS = ("<<<<<<<", "=======", ">>>>>>>", "|||||||")

SYSTEM_PROMPT = (
    "You resolve a git conflict. You receive three versions of one file: BASE "
    "(the common ancestor), OURS (the branch being rebased onto) and THEIRS "
    "(the commit being replayed). Return only the merged file content, with no "
    "commentary, no code fences and no conflict markers. Keep both intents when "
    "they do not contradict each other; when they do, keep THEIRS."
)

# Derived paths: (matcher, regeneration command, why this is derived).
# Matched by path segment so `packages/x/dist/y` and `dist/y` both count.
DERIVED_RULES = (
    ("pnpm-lock.yaml", "pnpm install --lockfile-only",
     "lockfile generated by pnpm; .gitattributes marks it merge=binary"),
    ("dist", "pnpm build",
     "tsc/Vite output of every workspace package (gitignored, never authored)"),
    ("dev-dist", "pnpm build",
     "Vite PWA service worker emitted by the pager build"),
    ("coverage", "pnpm test",
     "Vitest coverage report, a run artefact"),
    ("playwright-report", "pnpm e2e",
     "Playwright HTML report, a run artefact"),
    ("test-results", "pnpm e2e",
     "Playwright raw results, a run artefact"),
)
DERIVED_SUFFIX_RULES = (
    (".tsbuildinfo", "pnpm typecheck",
     "incremental tsc cache, rewritten by every typecheck"),
)
BINARY_EXTENSIONS = {
    ".png", ".jpg", ".jpeg", ".gif", ".webp", ".ico", ".woff", ".woff2", ".ttf",
    ".pdf", ".zip", ".gz", ".wasm", ".snap", ".sqlite", ".db",
}


def _segments(path):
    return [part for part in path.replace("\\", "/").split("/") if part]


def is_derived(path):
    """Return (command, why) when `path` is generated, else None."""
    name = _segments(path)[-1] if _segments(path) else path
    for rule_name, command, why in DERIVED_RULES:
        if rule_name == "pnpm-lock.yaml":
            if name == rule_name:
                return command, why
            continue
        if rule_name in _segments(path)[:-1]:
            return command, why
    for suffix, command, why in DERIVED_SUFFIX_RULES:
        if name.endswith(suffix):
            return command, why
    return None


def is_binary(path, raw=None):
    """Binary = known binary extension, or NUL bytes in the first 8 KiB."""
    if os.path.splitext(path)[1].lower() in BINARY_EXTENSIONS:
        return True
    if raw:
        return b"\0" in raw[:8192]
    return False


def classify_conflict(path, raw=None):
    """Return 'binary', 'derived' or 'source' for one conflicted path."""
    if is_binary(path, raw):
        return "binary"
    if is_derived(path):
        return "derived"
    return "source"


def merge_json(base, ours, theirs, path="", notes=None):
    """Merge two JSON values key by key; no key of either side is ever lost."""
    notes = [] if notes is None else notes
    if isinstance(ours, dict) and isinstance(theirs, dict):
        merged = {}
        for key in sorted(set(ours) | set(theirs)):
            if key not in theirs:
                merged[key] = ours[key]
            elif key not in ours:
                merged[key] = theirs[key]
            else:
                merged[key] = merge_json(base.get(key) if isinstance(base, dict) else None,
                                         ours[key], theirs[key],
                                         "%s.%s" % (path, key) if path else key, notes)
        return merged
    if isinstance(ours, list) and isinstance(theirs, list):
        extra = [item for item in theirs if item not in ours]
        return ours + extra
    if ours == theirs:
        return ours
    notes.append("%s: kept %r (theirs) over %r (ours)"
                 % (path or "<root>", theirs, ours))
    return theirs


def _parse_json(text):
    try:
        return json.loads(text)
    except (ValueError, TypeError):
        return None


def merge_package_json(base, ours, theirs):
    """Deterministic package.json merge. Returns (content, notes) or (None, notes)."""
    notes = []
    if _parse_json(ours) is None or _parse_json(theirs) is None:
        return None, ["one side is not valid JSON"]
    merged = merge_json(_parse_json(base or "{}"), _parse_json(ours),
                        _parse_json(theirs), "", notes)
    for field in ("dependencies", "devDependencies", "peerDependencies",
                  "optionalDependencies", "scripts"):
        if isinstance(merged.get(field), dict):
            merged[field] = {key: merged[field][key] for key in sorted(merged[field])}
    return json.dumps(merged, indent=2, ensure_ascii=False) + "\n", notes


def deterministic_resolve(path, kind, base, ours, theirs):
    """Leg that needs no model. Returns a result dict, or None when it declines."""
    if ours == theirs:
        return {"status": "resolved", "strategy": "identical", "content": ours,
                "notes": ["both sides had the same content"]}
    if kind == "derived":
        command, why = is_derived(path)
        return {"status": "regenerate", "strategy": "derived", "command": command,
                "notes": [why]}
    if os.path.basename(path) == "package.json":
        content, notes = merge_package_json(base, ours, theirs)
        if content is not None:
            return {"status": "resolved", "strategy": "json-merge",
                    "content": content, "notes": notes}
        return {"status": "unresolved", "strategy": "json-merge",
                "notes": notes + ["package.json could not be merged key by key"]}
    if kind == "binary":
        return {"status": "unresolved", "strategy": "binary",
                "notes": ["binary file differs on both sides; a human decides"]}
    return None


def llm_model():
    """Fireworks model id, overridable by HERMES_LLM_MODEL."""
    return (os.environ.get(MODEL_ENV) or "").strip() or FIREWORKS_DEFAULT_MODEL


def llm_available():
    """True when a Fireworks key is present. The value is never read out loud."""
    return bool((os.environ.get(KEY_ENV) or "").strip())


def build_prompt(path, base, ours, theirs):
    """One prompt, three versions, explicit separators."""
    parts = ["PATH: %s" % path]
    for label, text in (("BASE", base), ("OURS", ours), ("THEIRS", theirs)):
        parts.append("\n<<<<<<< %s\n%s\n>>>>>>> %s" % (label, text, label))
    return "\n".join(parts)


def accept_llm_output(reply, base="", ours="", theirs=""):
    """Return the reply when it is a plausible merged file, else None."""
    if not reply or not reply.strip():
        return None
    text = reply.strip("\n")
    if text.startswith("```") and text.rstrip().endswith("```"):
        text = text.split("\n", 1)[-1].rsplit("```", 1)[0].rstrip("\n")
    if not text.strip():
        return None
    for marker in MARKERS:
        if marker in text:
            return None
    biggest = max(len(base), len(ours), len(theirs))
    if biggest and len(text) > MAX_GROWTH * biggest + 2000:
        return None
    return text + "\n"


def call_fireworks(prompt):
    """POST the prompt to Fireworks. Returns the raw text, raises on failure."""
    import urllib.request

    body = json.dumps({
        "model": llm_model(),
        "messages": [
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": prompt},
        ],
        "temperature": 0,
        "max_tokens": 8192,
    }).encode()
    request = urllib.request.Request(FIREWORKS_URL, data=body, method="POST")
    request.add_header("Authorization", "Bearer " + os.environ[KEY_ENV].strip())
    request.add_header("Content-Type", "application/json")
    with urllib.request.urlopen(request, timeout=LLM_TIMEOUT) as response:
        payload = json.loads(response.read() or b"{}")
    choices = payload.get("choices") or []
    return (choices[0].get("message") or {}).get("content") if choices else None


def resolve_with_llm(path, base, ours, theirs, ask=None):
    """LLM leg. Returns merged text, or None when it declines or misbehaves."""
    if max(len(base), len(ours), len(theirs)) > MAX_LLM_SIDE:
        return None
    if ask is None:
        if not llm_available():
            return None
        ask = call_fireworks
    try:
        reply = ask(build_prompt(path, base, ours, theirs))
    except Exception as exc:  # network, auth, quota: the leg declines
        print("[resolve] LLM leg declined for %s: %s" % (path, type(exc).__name__),
              flush=True)
        return None
    return accept_llm_output(reply, base, ours, theirs)


def resolve_file(path, base, ours, theirs, ask=None):
    """Resolve one conflicted file: cheap proof first, LLM second, then escalate."""
    kind = classify_conflict(path, raw=(theirs or ours).encode("utf-8", "replace"))
    quick = deterministic_resolve(path, kind, base, ours, theirs)
    if quick is not None:
        quick["kind"] = kind
        quick["path"] = path
        return quick
    merged = resolve_with_llm(path, base, ours, theirs, ask=ask)
    if merged is not None:
        return {"status": "resolved", "strategy": "llm", "kind": kind,
                "path": path, "content": merged,
                "notes": ["merged by %s" % llm_model()]}
    return {"status": "unresolved", "strategy": "llm-declined", "kind": kind,
            "path": path, "notes": ["no model key or unusable model output"]}


def _expect(name, condition, problems):
    print("  %-52s %s" % (name, "ok" if condition else "FAIL"), flush=True)
    if not condition:
        problems.append(name)


def _selftest_kinds(problems):
    """Classification: derived, binary, source."""
    lock = deterministic_resolve("pnpm-lock.yaml", classify_conflict("pnpm-lock.yaml"),
                                 "", "a", "b")
    _expect("derived: lockfile is regenerated, not merged",
            lock["status"] == "regenerate" and lock["command"].startswith("pnpm install"),
            problems)
    _expect("derived: a lockfile is never classified as source",
            classify_conflict("pnpm-lock.yaml") == "derived", problems)
    _expect("derived: build output is derived",
            classify_conflict("packages/pager/dist/assets/app.js") == "derived",
            problems)
    _expect("binary: png is binary",
            classify_conflict("packages/pager/public/icon.png") == "binary", problems)


def _selftest_json(problems):
    """package.json merged key by key: nothing lost, keys sorted, trace kept."""
    base = '{"dependencies": {"left-pad": "1.0.0"}}'
    ours = '{"dependencies": {"left-pad": "1.0.0", "zod": "3.0.0"}, "name": "x"}'
    theirs = '{"dependencies": {"left-pad": "2.0.0", "hono": "4.0.0"}, "name": "x"}'
    merged, notes = merge_package_json(base, ours, theirs)
    data = _parse_json(merged or "{}") or {}
    deps = data.get("dependencies") or {}
    _expect("json-merge: no key is lost",
            set(deps) == {"left-pad", "zod", "hono"}, problems)
    _expect("json-merge: dependency keys are sorted",
            list(deps) == sorted(deps), problems)
    _expect("json-merge: the conflict is written down",
            any("left-pad" in note for note in notes), problems)


def _selftest_llm(problems):
    """The LLM leg, injected: a good reply resolves, a bad one is refused."""
    fake = lambda prompt: "const a = 1;\nexport default a;\n"
    llm = resolve_file("packages/core/src/limits.ts", "const a = 0;",
                       "const a = 0;\nconst b = 2;", "const a = 1;", ask=fake)
    _expect("llm: an injected leg resolves a source conflict",
            llm["status"] == "resolved" and llm["strategy"] == "llm", problems)
    bad = resolve_file("packages/core/src/limits.ts", "x", "y", "z",
                       ask=lambda prompt: "<<<<<<< HEAD\ny\n=======\nz\n>>>>>>> pr\n")
    _expect("llm: conflict markers are rejected", bad["status"] == "unresolved", problems)
    _expect("llm: an empty reply is rejected", accept_llm_output("   \n") is None, problems)
    _expect("llm: an absurd size is rejected",
            accept_llm_output("a" * 90000, "a", "b", "c") is None, problems)


def _selftest_wiring(problems):
    """The direct leg is Fireworks, and a key makes it available (value unread)."""
    _expect("wiring: the direct leg is Fireworks",
            FIREWORKS_URL == "https://api.fireworks.ai/inference/v1/chat/completions"
            and "fireworks" in llm_model(), problems)
    saved = os.environ.pop(KEY_ENV, None)
    _expect("wiring: no key => the leg is unavailable", llm_available() is False, problems)
    os.environ[KEY_ENV] = "selftest-placeholder"
    _expect("wiring: a Fireworks key => the leg is available",
            llm_available() is True, problems)
    os.environ.pop(KEY_ENV, None)
    if saved is not None:
        os.environ[KEY_ENV] = saved


def selftest():
    """In-memory cases, no secret, no network."""
    problems = []
    for group in (_selftest_kinds, _selftest_json, _selftest_llm, _selftest_wiring):
        group(problems)
    print("resolve selftest: %s" % ("OK" if not problems else "FAILED %s" % problems))
    return 1 if problems else 0


if __name__ == "__main__":
    if "--selftest" in sys.argv[1:]:
        sys.exit(selftest())
    print(__doc__.strip())
    sys.exit(0)
